#!/bin/sh
# Assemble b2f.S and regenerate src/b2f/b2f_pxe_image.h.
# Needs GNU binutils (as, ld, objcopy) and python3.
set -eu

here="$(cd "$(dirname "$0")" && pwd)"
out="$(cd "$here/../../src/b2f" && pwd)/b2f_pxe_image.h"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

as --32 -o "$tmp/b2f.o" "$here/b2f.S"
ld -m elf_i386 -Ttext=0x7c00 -e _start -o "$tmp/b2f.elf" "$tmp/b2f.o"
objcopy -O binary -j .text "$tmp/b2f.elf" "$tmp/b2f.pxe"

python3 - "$tmp/b2f.pxe" "$out" <<'EOF'
import sys

image = open(sys.argv[1], "rb").read()
lines = [
    "// Generated by tools/b2f_pxe/build.sh from tools/b2f_pxe/b2f.S - do not edit.",
    "#pragma once",
    "",
    "#include <stdint.h>",
    "",
    "static const uint8_t b2f_pxe_image[%d] = {" % len(image),
]
for i in range(0, len(image), 16):
    lines.append("    " + " ".join("0x%02x," % b for b in image[i:i + 16]))
lines.append("};")
open(sys.argv[2], "w").write("\n".join(lines) + "\n")
EOF

echo "Wrote $out"
